create or replace function public.admin_crud_capability_catalog()
returns jsonb language plpgsql security definer set search_path to 'public','pg_temp' as $$
declare v_result jsonb;
begin
 if auth.uid() is null then raise exception 'authentication required'; end if;
 if not exists(select 1 from public.profiles where id=auth.uid() and (is_admin=true or lower(coalesce(role::text,'')) in ('admin','owner','platform_admin'))) then raise exception 'admin authorization required'; end if;
 select coalesce(jsonb_agg(jsonb_build_object('resource',v.resource,'read',true,'create',not(v.resource=any(v.read_only)),'update',not(v.resource=any(v.read_only)),'delete',not(v.resource=any(v.read_only)),'read_only',v.resource=any(v.read_only),'primary_key',coalesce((select a.attname from pg_index i join pg_attribute a on a.attrelid=i.indrelid and a.attnum=any(i.indkey) where i.indrelid=('public.'||v.resource)::regclass and i.indisprimary limit 1),'id')) order by v.resource),'[]'::jsonb) into v_result
 from (select unnest(array['profiles','businesses','locations','location_hours','amenities','location_amenities','location_fixtures','location_photos','qr_codes','check_ins','reviews','review_photos','review_likes','review_amenity_feedback','favorites','follows','social_posts','social_post_likes','social_post_comments','social_post_saves','social_post_reports','social_activity','reports','badges','user_badges','point_transactions','level_definitions','user_streaks','progression_actions','progression_games','progression_challenges','social_challenge_entries','progression_metric_events','business_campaigns','business_events','event_rsvps','contests','contest_entries','promotions','promotion_redemptions','partner_programs','partner_agreements','partner_program_locations','partner_program_memberships','membership_clubs','club_memberships','single_use_access_offers','single_use_access_purchases','business_certifications','certification_tiers','enterprise_partner_networks','enterprise_partner_network_members','enterprise_partner_network_metrics','enterprise_partner_campaigns','enterprise_partner_campaign_outcomes','enterprise_partner_allocations','business_engagement_attributions','business_metric_leaderboards','analytics_events','preferred_location_activations','preferred_usage_events','location_visits','location_bathroom_verifications','location_verification_points','support_requests','user_feedback','account_deletion_requests','admin_capability_audit','demo_identity_registry','subscription_plans','subscriptions','pricing_catalog','app_business_memberships','business_overview','community_leaderboard','contest_leaderboards','partner_preferred_usage_analytics','preferred_business_analytics','public_locations','public_profiles','user_progression_metric_summary','notifications','messages','route_events','route_plans','route_stops','family_groups','family_members']) resource, array['profiles','businesses','subscriptions','admin_capability_audit','account_deletion_requests','analytics_events','progression_metric_events','point_transactions','user_streaks','social_activity','notifications','messages','app_business_memberships','business_overview','community_leaderboard','contest_leaderboards','partner_preferred_usage_analytics','preferred_business_analytics','public_locations','public_profiles','user_progression_metric_summary','event_rsvps','family_groups','family_members','route_events','route_plans','route_stops','enterprise_partner_networks','enterprise_partner_network_members','enterprise_partner_network_metrics','enterprise_partner_campaigns','enterprise_partner_campaign_outcomes','enterprise_partner_allocations','business_certifications','business_engagement_attributions','business_metric_leaderboards','preferred_location_activations','preferred_usage_events','location_visits','location_bathroom_verifications','location_verification_points','single_use_access_purchases','promotion_redemptions','contest_entries','partner_agreements','partner_program_locations','partner_program_memberships','club_memberships','user_badges','social_post_likes','social_post_comments','social_post_saves','social_post_reports','review_likes','review_photos','review_amenity_feedback'] read_only) v
 where to_regclass('public.'||v.resource) is not null;
 return v_result;
end; $$;
grant execute on function public.admin_crud_capability_catalog() to authenticated;
